def clean(pe):
    ks=sorted(pe); out=dict(pe); flag=set()
    for i in range(1,len(ks)-1):
        a,b,c=pe[ks[i-1]],pe[ks[i]],pe[ks[i+1]]
        if b<0.75*min(a,c) or b>1.33*max(a,c): out[ks[i]]=round((a+c)/2,4); flag.add(ks[i])
    return out,flag
def fields(pe,flag,m,px):
    p=pe.get(m)
    if p is None: return dict(eps_ttm=None,pe_ttm=None,pe_estimate=False)
    return dict(eps_ttm=round(px/p,2) if px else None,pe_ttm=round(p,2),pe_estimate=m in flag)
